<script setup lang="ts">
import {ref,reactive,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {Button,Input,NativeSelect} from '@openclaw-plugins/control-ui-kit';
import type {Person,PeopleGroupSyncRun} from '../../agent-repo-api/people.mjs';
type Page={people:Person[];total:number;nextOffset:number|null;stats?:{giteaSources?:Record<string,number>;missing?:Record<string,number>}};
type Sync={available:boolean;accounts?:{accountId:string}[];onJoin?:boolean;reason?:string;run?:PeopleGroupSyncRun|null};
const props=withDefaults(defineProps<{invoke:<T>(action:string,payload:Record<string,unknown>)=>Promise<T>;canWrite:boolean;safe:(value:unknown)=>string;isGroup?:boolean;inline?:boolean;filters?:Record<string,string>}>(),{isGroup:false,inline:false,filters:()=>({})});
const emit=defineEmits<{loaded:[page:Page];close:[];busy:[value:boolean]}>();
const page=ref<Page>({people:[],total:0,nextOffset:null}),query=ref(''),offset=ref(0),loading=ref(true),busy=ref(false),notice=ref(''),selected=ref(''),editing=ref(''),confirmDelete=ref('');
const drafts=reactive(new Map<string,Record<string,string>>());
const person=computed(()=>page.value.people.find(p=>p.id===selected.value)??page.value.people[0]);
const draft=computed(()=>editing.value?drafts.get(editing.value):undefined);
const departments=(p:Person)=>p.departments.map(d=>d.name||d.id).join('、');
let alive=true,epoch=0,syncEpoch=0,timer:ReturnType<typeof setTimeout>|undefined;
const syncInfo=ref<Sync>(),syncAccount=ref(''),syncing=ref(false),syncStatus=ref('');
const syncLabel=computed(()=>props.inline?'同步所选群成员':'同步本群成员');
const canSync=computed(()=>props.canWrite&&!busy.value&&!syncing.value&&syncInfo.value?.available&&syncInfo.value.run?.status!=='running'&&((syncInfo.value.accounts?.length??0)<=1||!!syncAccount.value));
function summary(run:PeopleGroupSyncRun){const details=`已保存 ${run.saved} 人（新增 ${run.created}、更新 ${run.updated}），通讯录资料 ${run.profiled} 人，仅基本身份 ${run.identityOnly} 人。`;return run.status==='running'?`正在同步：已处理 ${run.processed} / ${run.discovered} 人…`:run.status==='completed'?'同步完成：'+details:run.status==='partial'?'部分同步完成：'+details+' 可重试同步补全。':run.status==='cancelled'?'同步已中断，已保存的资料会保留。':'同步失败，请核对群访问和通讯录权限后重试。';}
async function load(){const token=++epoch;loading.value=true;notice.value='';try{const next=await props.invoke<Page>('people',{...props.filters,query:query.value,offset:offset.value});if(!alive||token!==epoch)return;page.value=next;editing.value='';confirmDelete.value='';drafts.clear();if(!next.people.some(p=>p.id===selected.value))selected.value=next.people[0]?.id??'';emit('loaded',next);}catch(e){if(alive&&token===epoch)notice.value=props.safe(e instanceof Error?e.message:e);}finally{if(alive&&token===epoch)loading.value=false;}}
async function loadSync(){clearTimeout(timer);if(!alive||!props.isGroup)return;const token=++syncEpoch;try{const next=await props.invoke<Sync>('peopleSyncInfo',syncAccount.value?{accountId:syncAccount.value}:{});if(!alive||token!==syncEpoch)return;const wasRunning=syncInfo.value?.run?.status==='running';syncInfo.value=next;if(!syncAccount.value&&next.accounts?.length===1)syncAccount.value=next.accounts[0]!.accountId;syncStatus.value=next.run?summary(next.run):next.available?(next.onJoin?'已启用入群自动同步，需飞书订阅入群事件。':'入群自动同步已关闭，可手动同步。'):(next.reason||'当前群暂不可同步');if(next.run?.status==='running')timer=setTimeout(loadSync,1500);if(wasRunning&&next.run?.status!=='running'&&!editing.value)await load();}catch(e){if(alive&&token===syncEpoch)syncStatus.value='无法读取同步状态：'+props.safe(e instanceof Error?e.message:e);}}
async function startSync(){if(!canSync.value)return;syncing.value=true;try{const run=await props.invoke<PeopleGroupSyncRun>('syncPeople',syncAccount.value?{accountId:syncAccount.value}:{});if(!alive)return;syncInfo.value={...syncInfo.value!,run};syncStatus.value=summary(run);await loadSync();}catch(e){if(alive)syncStatus.value='无法开始同步：'+props.safe(e instanceof Error?e.message:e);}finally{if(alive)syncing.value=false;}}
async function mutate(action:string,payload:Record<string,unknown>){if(!props.canWrite||busy.value||!alive)return;const token=epoch;busy.value=true;notice.value='';try{await props.invoke(action,payload);if(alive&&token===epoch){offset.value=0;await load();}}catch(e){if(alive&&token===epoch)notice.value=props.safe(e instanceof Error?e.message:e);}finally{if(alive)busy.value=false;}}
function edit(p:Person){if(!drafts.has(p.id))drafts.set(p.id,{name:p.name??'',email:p.email??'',departments:p.departments.map(d=>d.name||d.id).join(', '),giteaUsername:p.giteaUsername??''});editing.value=p.id;confirmDelete.value='';}
function save(){const p=person.value,d=draft.value;if(!p||!d)return;void mutate('updatePerson',{id:p.id,revision:p.revision,patch:{name:d.name,email:d.email,giteaUsername:d.giteaUsername||null,departments:d.departments!.split(/[,，]/).map(s=>s.trim()).filter(Boolean).map(name=>p.departments.find(x=>x.name===name)||{id:name,name})}});}
function reset(p:Person){void mutate('updatePerson',{id:p.id,revision:p.revision,patch:{name:null,email:null,departments:null,giteaUsername:null}});}
function search(){offset.value=0;void load();}
function escape(e:KeyboardEvent){if(e.key!=='Escape'||busy.value)return;if(editing.value){e.preventDefault();e.stopPropagation();editing.value='';confirmDelete.value='';}else if(!props.inline){e.preventDefault();emit('close');}}
watch(busy,value=>emit('busy',value));
watch(()=>props.filters,search,{deep:true});watch(()=>props.canWrite,()=>{editing.value='';confirmDelete.value='';drafts.clear();});
onMounted(()=>{void load();void loadSync();});onBeforeUnmount(()=>{alive=false;epoch++;syncEpoch++;clearTimeout(timer);});
defineExpose({refresh:search,escape});
</script>
<template>
<section class="ar-people-dialog" aria-label="人员资料管理" @keydown="escape">
 <header class="ar-people-header"><div class="ar-people-heading"><div class="ar-people-title-row"><h2>人员资料</h2><span class="ar-people-count">{{page.total}} 位同事</span></div><p>管理飞书联系人与 Gitea 账号映射</p></div><Button v-if="!inline" variant="ghost" aria-label="关闭人员资料" :disabled="busy" @click="emit('close')">关闭</Button></header>
 <div class="ar-people-toolbar"><form class="ar-people-search" @submit.prevent="search"><Input v-model="query" type="search" aria-label="搜索人员" placeholder="搜索姓名、部门、邮箱或账号" :disabled="busy"/><Button type="submit" :disabled="busy||loading">搜索</Button></form><Button variant="outline" aria-label="刷新人员" :disabled="busy||loading" @click="load">{{loading?'刷新中…':'刷新'}}</Button><template v-if="isGroup"><NativeSelect v-if="(syncInfo?.accounts?.length??0)>1" v-model="syncAccount" aria-label="同步使用的飞书账号" :disabled="syncing||syncInfo?.run?.status==='running'" @update:model-value="()=>{syncInfo=undefined;loadSync();}"><option value="">选择飞书账号</option><option v-for="account in syncInfo?.accounts" :key="account.accountId" :value="account.accountId">{{safe(account.accountId)}}</option></NativeSelect><Button :aria-label="syncLabel" :disabled="!canSync" @click="startSync">{{syncing||syncInfo?.run?.status==='running'?'同步中…':syncLabel}}</Button></template></div>
 <p v-if="syncStatus" class="ar-people-sync-status" role="status">{{safe(syncStatus)}}</p><p v-if="notice" class="ar-people-notice ar-people-error" role="alert">{{notice}}</p>
 <div class="ar-people-content" :class="{'is-empty':!page.people.length}">
 <div v-if="page.people.length" class="ar-people-roster"><div class="ar-people-list" aria-label="人员列表"><div class="ar-people-list-caption">联系人</div><button v-for="p in page.people" :key="p.id" type="button" class="ar-people-person" :class="{'is-selected':selected===p.id}" :aria-label="'查看 '+(p.name||'姓名未知')" :aria-pressed="selected===p.id" :disabled="busy" @click="selected=p.id;editing='';confirmDelete='';notice=''"><span class="ar-people-avatar">{{(p.name||'?').slice(-2)}}</span><span class="ar-people-person-text"><strong>{{safe(p.name||'姓名未知')}}</strong><span>{{safe(departments(p)||p.email||'部门暂未获取')}}</span></span></button></div><div class="ar-people-pagination"><span>{{page.total}} 位人员 · 第 {{Math.floor(offset/50)+1}} 页</span><div v-if="offset>0||page.nextOffset!==null"><Button variant="ghost" :disabled="busy||loading||offset===0" @click="offset=Math.max(0,offset-50);load()">上一页</Button><Button variant="ghost" :disabled="busy||loading||page.nextOffset===null" @click="offset=page.nextOffset!;load()">下一页</Button></div></div></div>
 <div class="ar-people-detail" :class="{'is-editing':editing}"><template v-if="person"><div class="ar-people-identity"><span class="ar-people-avatar large">{{(person.name||'?').slice(-2)}}</span><div><div class="ar-people-name-line"><h3>{{safe(person.name||'姓名未知')}}</h3><span class="ar-people-badge" :class="person.giteaSource==='admin'?'confirmed':person.giteaUsername?'pending':'unknown'">{{person.giteaSource==='admin'?'已确认':person.giteaUsername?'待核验':'未关联'}}</span></div><p>{{safe(departments(person)||'部门暂未获取')}}</p></div></div>
 <form v-if="draft" class="ar-people-form" @submit.prevent="save"><div class="ar-people-section-heading"><h4>编辑资料</h4><p>保存后优先使用此处的更正。</p></div><div class="ar-people-edit-grid"><label v-for="[key,label] in [['name','姓名'],['departments','部门（多个用逗号分隔）'],['email','邮箱'],['giteaUsername','Gitea 账号']]" :key="key" class="ar-people-edit-field"><span>{{label}}</span><Input v-model="draft[key!]" :aria-label="'编辑'+label" :type="key==='email'?'email':'text'" :disabled="busy"/><small v-if="key==='giteaUsername'">填写用户名，无需添加 @。</small></label></div><div class="ar-people-form-actions"><Button variant="outline" :disabled="busy" @click="editing=''">取消编辑</Button><Button type="submit" aria-label="保存人员资料" :disabled="busy">{{busy?'正在保存…':'保存更改'}}</Button></div></form>
 <template v-else><dl class="ar-people-facts"><div class="ar-people-field"><dt>邮箱</dt><dd>{{safe(person.email||'暂未获取')}}</dd></div><div class="ar-people-field"><dt>Gitea 账号</dt><dd>{{safe(person.giteaUsername?'@'+person.giteaUsername:'暂未获取')}}</dd><p>{{person.giteaSource==='admin'?'管理员已确认此映射。':person.giteaUsername?'根据邮箱前缀推导，建单前需核验。':'关联后可用于 Issue 记录人与指派人。'}}</p></div></dl><details class="ar-people-technical"><summary>身份标识与采集信息</summary><dl><div v-for="[label,value] in [['飞书账号 / 应用',person.accountId+' / '+person.appId],['OpenID',person.openId],['最近采集',new Date(person.observedAt).toLocaleString()]]" :key="label" class="ar-people-field"><dt>{{label}}</dt><dd>{{safe(value)}}</dd></div></dl></details><div v-if="canWrite" class="ar-people-detail-actions"><Button aria-label="编辑人员" :disabled="busy" @click="edit(person)">编辑资料</Button><details class="ar-people-more"><summary>更多操作</summary><div class="ar-people-options"><Button variant="ghost" :disabled="busy" @click="reset(person)">恢复飞书资料与邮箱推导</Button><Button variant="destructive" :disabled="busy" @click="confirmDelete=person.id">删除人员</Button></div></details></div><div v-if="confirmDelete===person.id&&canWrite" class="ar-people-confirm"><div><strong>删除这份本地资料？</strong><p>资料将移入回收站，保留期内可恢复；不会修改飞书通讯录。</p></div><div><Button variant="outline" :disabled="busy" @click="confirmDelete=''">取消删除</Button><Button variant="destructive" :disabled="busy" @click="mutate('deletePerson',{id:person.id,revision:person.revision,confirmed:true})">确认删除本地资料</Button></div></div></template>
 </template><div v-else class="ar-people-empty"><span class="ar-people-eyebrow">人员目录</span><h3>{{loading?'正在加载人员资料':notice?'人员资料读取失败':query?'没有找到相关人员':'还没有人员资料'}}</h3><p>{{loading?'请稍候，正在读取本地人员目录。':notice?'可刷新重试。':query?'试试姓名、部门、邮箱或 Gitea 账号，也可以清空搜索条件。':'与此 Agent 聊天、在消息中被原生 @，或从飞书同步后，人员资料会自动出现在这里。'}}</p><Button v-if="!loading&&query" variant="outline" @click="query='';search()">清空搜索</Button></div></div></div>
 <footer class="ar-people-footer"><span>资料来自飞书，人工更正优先保留。</span><span>仅用于身份关联，不改变操作权限。</span></footer>
</section>
</template>
